#include <jxl/encode.h>
#include <jxl/color_encoding.h>
#include <vector>
#include <cstdio>
int main(int argc,char**argv){if(argc!=2)return 1;auto*e=JxlEncoderCreate(nullptr);JxlBasicInfo info;JxlEncoderInitBasicInfo(&info);info.xsize=18;info.ysize=20;info.bits_per_sample=16;info.uses_original_profile=JXL_TRUE;JxlEncoderUseContainer(e,JXL_TRUE);if(JxlEncoderSetBasicInfo(e,&info)!=JXL_ENC_SUCCESS)return 2;JxlColorEncoding color;JxlColorEncodingSetToLinearSRGB(&color,JXL_FALSE);if(JxlEncoderSetColorEncoding(e,&color)!=JXL_ENC_SUCCESS)return 3;auto*s=JxlEncoderFrameSettingsCreate(e,nullptr);JxlEncoderSetFrameLossless(s,JXL_TRUE);JxlEncoderFrameSettingsSetOption(s,JXL_ENC_FRAME_SETTING_EFFORT,5);std::vector<unsigned short> pixels(18*20*3);unsigned short values[]={0,1,255,256,32767,32768,65534,65535};for(size_t i=0;i<pixels.size();i++)pixels[i]=values[i%8];JxlPixelFormat format{3,JXL_TYPE_UINT16,JXL_NATIVE_ENDIAN,0};if(JxlEncoderAddImageFrame(s,&format,pixels.data(),pixels.size()*2)!=JXL_ENC_SUCCESS)return 4;JxlEncoderCloseInput(e);std::vector<unsigned char> encoded(65536);auto*next=encoded.data();size_t available=encoded.size();if(JxlEncoderProcessOutput(e,&next,&available)!=JXL_ENC_SUCCESS)return 5;FILE*f=fopen(argv[1],"wb");fwrite(encoded.data(),1,encoded.size()-available,f);fclose(f);JxlEncoderDestroy(e);return 0;}
